 // src/components/Questions/QuestionDetails.js

import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import './QuestionDetails.css';
import HomeIcon from '../Common/HomeIcon';
import AnswerForm from '../Answers/AnswerForm';
// Importă ambele funcții, inclusiv deleteAnswer
import { getQuestionById, getAnswersByQuestionId, deleteAnswer } from '../../services/api';

function QuestionDetails() {
  const { id } = useParams();
  const [question, setQuestion] = useState(null);
  const [answers, setAnswers] = useState([]);
  const [likes, setLikes] = useState(0);
  // Stare pentru ID-ul utilizatorului curent logat
  const [currentUserId, setCurrentUserId] = useState(null);

  // Folosim un alt useEffect sau combinăm pentru a obține ID-ul utilizatorului logat
    useEffect(() => {
    // Verifică doar prezența token-ului pentru a ști dacă utilizatorul este logat (pentru afișarea condițională a elementelor)
    // ID-ul utilizatorului pentru ștergere va fi obținut dintr-o altă sursă (vezi Pasul 2 & 3)
    const token = localStorage.getItem('token');
    if (token) {
        // Momentan, setăm un placeholder sau lăsăm null. Vom obține userId-ul real în Pasul 3.
        // Sau dacă stocați userId separat (vezi Pasul 2), citiți-l aici.
        const userId = localStorage.getItem('userId'); // <-- Încercăm să citim userId separat
        setCurrentUserId(userId ? Number(userId) : null); // Setează userId dacă există și e număr
    } else {
        setCurrentUserId(null); // Utilizator nelogat
    }


    // Fetch Question details
    getQuestionById(id)
      .then(data => {
        setQuestion(data);
        setLikes(data.voteScore || 0); // Folosește voteScore de la backend
      })
      .catch(err => console.error('Eroare la încărcarea întrebării:', err));

    // Fetch Answers for the question
    getAnswersByQuestionId(id)
      .then(data => setAnswers(data))
      .catch(err => console.error('Eroare la încărcarea răspunsurilor:', err));

  }, [id]); // Dependența [id]

  // Handler pentru voturi (rămâne neschimbat)
  const handleVote = type => {
      // Această logică actualizează doar vizual scorul pe frontend.
      // Ar trebui să apelați și un endpoint de backend pentru a înregistra votul.
    setLikes(prev => prev + (type === 'like' ? 1 : -1));
  };

  // Noul handler pentru ștergerea unui răspuns
  const handleDeleteAnswer = async (answerId) => {
    // Cere confirmare înainte de ștergere
    if (window.confirm('Sigur doriți să ștergeți acest răspuns?')) {
      try {
        // Apelăm funcția API de ștergere, trimițând ID-ul răspunsului și ID-ul utilizatorului logat
        const result = await deleteAnswer(answerId, currentUserId);
        console.log("Backend response for delete:", result.message); // Logăm mesajul de la backend

        // Verificăm mesajul de succes de la backend
        if (result.message === "Answer deleted successfully.") {
            // Dacă ștergerea a avut succes pe backend, actualizăm starea locală
            setAnswers(prevAnswers => prevAnswers.filter(answer => answer.id !== answerId));
             alert('Răspuns șters cu succes!');
        } else {
             // Afișăm mesajul de eroare trimis de backend (ex: "You are not the author.")
             alert('Nu s-a putut șterge răspunsul: ' + result.message);
        }

      } catch (error) {
        // Prindem erorile de rețea sau alte excepții din funcția 'request'
        console.error('Eroare la apelul deleteAnswer API:', error);
        alert('A apărut o eroare la ștergerea răspunsului.');
      }
    }
  };


  // Afișăm "Se încarcă..." până când detaliile întrebării sunt disponibile
  if (!question) {
    return <p>Se încarcă...</p>;
  }

  return (
    <div className="question-details-container">
      <HomeIcon />

      <h2>{question.title}</h2>
      <p><strong>Autor:</strong> {question.user?.username || 'Anonim'}</p>
      <p><strong>Data:</strong> {question.date}</p>
      <p><strong>Conținut:</strong> {question.text}</p>

      <p>
        <strong>Etichete:</strong>{' '}
        {(question.questionTags || []).map(qt =>
          <span className="tag" key={qt.id}>{qt.tag.name}</span>
        )}
      </p>

      {/* Secțiunea de voturi (rămâne neschimbată, dar ar trebui conectată la backend) */}
      <div className="like-buttons">
        {/* Butoanele de vot ar trebui și ele să cheme API-ul de voturi */}
        <button onClick={() => handleVote('like')}>👍</button>
        <button onClick={() => handleVote('dislike')}>👎</button>
        <span>{likes} voturi</span>
      </div>

      <h3>Răspunsuri:</h3>

      {/* Lista de Răspunsuri */}
      {answers.length === 0 ? (
        <p><i>Încă nu există răspunsuri pentru această întrebare.</i></p>
      ) : (
        <ul>
          {answers.map(answer => (
            <li key={answer.id}>
              <p>{answer.text}</p>
              <p style={{ fontSize: '0.85em', color: '#666' }}>
                — {answer.user?.username || 'Utilizator necunoscut'}
                {/* Condiție pentru afișarea butonului Șterge:
                    1. currentUserId nu este null (utilizatorul este logat)
                    2. answer.user există (răspunsul are un autor asociat)
                    3. ID-ul autorului răspunsului (answer.user.id) este egal cu ID-ul utilizatorului logat (currentUserId)
                */}
                {currentUserId !== null && answer.user && answer.user.id === currentUserId && (
                    <button
                        onClick={() => handleDeleteAnswer(answer.id)} // Apelează handler-ul de ștergere cu ID-ul răspunsului
                        style={{ marginLeft: '10px', fontSize: '0.8em', cursor: 'pointer', color: 'red' }} // Stil simplu pentru buton
                    >
                        Șterge
                    </button>
                )}
              </p>
            </li>
          ))}
        </ul>
      )}

      {/* Formularul de Adăugare Răspuns - Afișat doar dacă utilizatorul este logat */}
      {currentUserId && (
           <AnswerForm
                questionId={id}
                // Când un răspuns nou e trimis cu succes din AnswerForm, îl adăugăm la lista locală
                onAnswerSubmitted={(newAnswer) => {
                    // Presupunem că newAnswer conține răspunsul nou creat returnat de backend,
                    // inclusiv ID-ul și user-ul complet cu ID.
                    setAnswers(prevAnswers => [...prevAnswers, newAnswer]);
                }}
            />
      )}

    </div>
  );
}

export default QuestionDetails;
